<template><div><Button @click="$emit('back')">返回记录列表</Button><Button :loading="loading" @click="load">刷新当前事实</Button><Alert v-if="error" type="error" show-icon>{{error}}</Alert><OperationRecovery :name="operationName" :revision="revision" @recovered="recovered"/><Spin v-if="loading&&!data" fix/><template v-if="data"><h2>{{data.storeName}} · 订单资金</h2><p class="intro">{{data.basis}}。模式：{{label(data.mode)}}，币种 {{data.currency}}。</p><Alert v-if="data.blockReason" type="warning" show-icon>原交易证据待核实，缺少的实际金额保持空值。请核对原付款与历史快照。</Alert><section class="detail-section"><h3>原付款与履约</h3><dl class="facts"><div v-for="row in identity" :key="row[0]" class="fact"><dt>{{row[0]}}</dt><dd>{{row[1]}}</dd></div></dl></section><section class="detail-section"><h3>实际资金事实</h3><dl class="facts"><div v-for="row in actual" :key="row[0]" class="fact"><dt>{{row[0]}}</dt><dd class="money">{{row[1]}}</dd></div></dl><p class="meta">实际净额 = 原实付 − 成功商品退款 − 成功费用退款 − 成功分账 + 成功回退。手续费证据未提供时不填零。</p></section><section class="detail-section" v-if="data.snapshot"><h3>历史规则与测算</h3><dl class="facts"><div v-for="row in measured" :key="row[0]" class="fact"><dt>{{row[0]}}</dt><dd>{{row[1]}}</dd></div></dl><p class="meta">测算按原订单历史规则，配送费不计佣；不代表已成功分账。</p></section><section v-if="task" class="detail-section"><h3>当前原资金请求</h3><dl class="facts"><div v-for="row in selected" :key="row[0]" class="fact"><dt>{{row[0]}}</dt><dd>{{row[1]}}</dd></div></dl><h4 v-if="task.kind==='SHARE'">原接收明细</h4><div v-if="task.kind==='SHARE'" class="table-scroll"><Table :columns="receiverColumns" :data="task.receiverDetails||[]" no-data-text="尚无可信接收明细证据"/></div><Form v-if="task.canRecover" label-position="top"><FormItem label="恢复原因 *"><Input v-model="reason" type="textarea" :maxlength="500" :disabled="busy" placeholder="说明原请求核实与恢复原因"/></FormItem><Checkbox v-if="task.retryAllowed&&task.state==='FAILED'" v-model="retry" :disabled="busy">已核实渠道允许按原请求再次发送</Checkbox><div class="actions"><Button type="primary" :loading="busy" :disabled="pending" @click="recover">查询原请求并恢复</Button></div><p class="meta">保留原渠道单号；渠道已成功时只恢复本地处理。未知结果先查原请求。</p></Form></section><h3>商品与费用退款义务</h3><div class="table-scroll"><Table :columns="obligationColumns" :data="data.obligations||[]" no-data-text="暂无退款义务"/></div><h3>执行批次</h3><div class="table-scroll"><Table :columns="batchColumns" :data="data.batches||[]" no-data-text="暂无执行批次"/></div><h3>分账、回退、退款与完结记录</h3><div class="table-scroll"><Table :columns="taskColumns" :data="data.tasks||[]" no-data-text="暂无资金请求"/></div><h3>本订单异常</h3><div class="table-scroll"><Table :columns="exceptionColumns" :data="data.exceptions||[]" no-data-text="暂无已记录异常"/></div><Alert v-if="data.protection" type="warning" show-icon>该原交易存在保护状态，不能恢复正常履约。迟到付款只可依据可信原交易建立独立退款义务。<div v-if="canRecover" class="actions"><Input v-model="reason" :maxlength="500" placeholder="迟到付款处理原因" style="width:400px"/><Button :loading="busy" :disabled="pending" @click="late">建立原路退回义务</Button></div></Alert><h3 v-if="history.length">原操作审计</h3><div class="history" v-for="row in history" :key="row.at"><p>{{row.reason}}</p><p class="meta">{{date(row.at)}}</p></div></template></div></template>
<script>
import {s45Read,s45Commands} from '@/api/stage45';import {managerSession} from '@/libs/manager-session';import {money,date,label,percent} from '../presentation.cjs';import OperationRecovery from './OperationRecovery.vue';
const col=(title,key,format)=>({title,key,minWidth:150,...(format?{render:(h,{row})=>h('span',format(row[key]))}:{})});
export default{components:{OperationRecovery},props:{id:String,taskMode:Boolean},data(){return{data:null,task:null,history:[],permissions:[],reason:'',retry:false,loading:false,busy:false,error:'',ticket:0,selectionTicket:0,revision:0,receiverColumns:[col('渠道明细号','detailId'),col('接收身份','account'),col('明细金额','amountCent',money),col('明细状态','state',label),col('渠道成功时间','succeededAt',date)],obligationColumns:[col('义务类型','kind',label),col('原售后','afterSaleId'),col('金额','amountCent',money),col('当前状态','state',label),col('执行批次','batchId'),col('申请时间','applicationAt',date),col('核准时间','approvedAt',date),col('本地回写时间','succeededAt',date)],batchColumns:[col('批次','id'),col('商品退款','goodsCent',money),col('费用退款','feeCent',money),col('本批目标佣金','targetCommissionCent',money),col('必要回退','requiredReturnCent',money),col('状态','state',label)],exceptionColumns:[col('异常编号','id'),col('待核实原因','explanation'),col('观察次数','observationCount'),col('状态','state',label),col('最近发生','updatedAt',date)]}},computed:{operationName(){return this.task?'task:'+this.task.id:'late:'+this.id},pending(){this.revision;return s45Commands.pending(this.operationName)},canRecover(){return this.permissions.includes('funds.recover')},identity(){const d=this.data;return [['子订单号',d.orderSn],['原合单号',d.tradeSn],['所属合单可信实付（仅父级核对）',money(d.tradePaidCent)],['合单子单数量',d.tradeChildCount==null?'待核实':d.tradeChildCount],['原付款状态',label(d.paymentState)],['履约状态',d.fulfillmentEnded?'未交付商品已退清，履约结束':label(d.fulfillmentPhase)],['原商品款',money(d.goodsCent)],['原履约费',money(d.freightCent)],['创建时间',date(d.createdAt)],['未决退款义务',money(d.pendingObligationCent)]]},actual(){const d=this.data;return [['可信原实付',money(d.paidCent)],['成功商品退款',money(d.goodsRefundCent)],['成功费用退款',money(d.feeRefundCent)],['成功分账',money(d.sharedCent)],['成功回退',money(d.returnedCent)],['当前实际佣金',money(d.actualCommissionCent)],['当前资金净额',money(d.netCent)],['手续费',d.feeCent==null?'证据待核实':money(d.feeCent)],['独立完结 / 解冻',d.finished?'已取得成功证据':'尚未取得成功证据']]},measured(){const s=this.data.snapshot;return [['原规则版本',s.ruleId+' / '+s.ruleRevision],['原协议',s.agreementId],['历史费率',percent(s.rateBps)],['原佣金测算',money(s.originalCommissionCent)],['退款后目标佣金',money(this.data.targetCommissionCent)],['原二级商户',s.subMchid],['历史接收关系',s.receiverEvidence==='HISTORICAL_SNAPSHOT'?'原交易快照可核验':'证据缺失']]},selected(){const t=this.task;return [['类型',label(t.kind)],['稳定渠道请求号',t.requestNo],['金额',money(t.amountCent)],['资金状态',label(t.state)],['渠道认定成功金额',money(t.succeededCent)],['接收明细状态',label(t.detailState)],['本地回写',t.applied?'已处理':'待恢复'],['渠道受理时间',date(t.acceptedAt)],['渠道成功时间',date(t.succeededAt)],['本次观察时间',date(t.observedAt)],['当前处理说明',t.reason||'暂无已记录阻断']]},taskColumns(){return [col('类型','kind',label),col('原请求号','requestNo'),col('申请金额','amountCent',money),col('成功金额','succeededCent',money),col('状态','state',label),{title:'本地处理',minWidth:120,render:(h,{row})=>h('span',row.applied?'已回写':'待处理')},{title:'操作',width:120,render:(h,{row})=>h('Button',{props:{size:'small'},on:{click:()=>this.selectTask(row.id)}},'核对原请求')}] }},watch:{id:{handler(){this.load()},immediate:true},taskMode(){this.load()}},beforeDestroy(){this.ticket++;this.selectionTicket++;this.data=null;this.task=null},methods:{money,date,label,async load(){this.selectionTicket++;const ticket=++this.ticket,owner=managerSession.snapshot();this.loading=true;this.error='';try{const [v,c]=await Promise.all([s45Read(this.taskMode?'/tasks/'+this.id:'/orders/'+this.id+'/funds'),s45Read('/context')]);if(ticket===this.ticket&&managerSession.sameSession(owner)){this.data=this.taskMode?v.order:v;this.task=this.taskMode?v.task:null;this.history=v.history||[];this.permissions=c.permissions}}catch(e){if(ticket===this.ticket){this.data=null;this.task=null;this.error=e.message}}finally{if(ticket===this.ticket)this.loading=false}},async selectTask(id){const ticket=++this.selectionTicket,view=this.ticket,owner=managerSession.snapshot();this.error='';this.task=null;this.history=[];try{const v=await s45Read('/tasks/'+id);if(ticket!==this.selectionTicket||view!==this.ticket||!managerSession.sameSession(owner))return;this.task=v.task;this.history=v.history||[];this.reason='';this.retry=false}catch(e){if(ticket===this.selectionTicket&&view===this.ticket){this.task=null;this.history=[];this.error=e.message}}},async recover(){if(!this.task||this.busy||this.pending)return;if(this.reason.trim().length<2){this.error='请填写至少2字的恢复原因。';return}this.$Modal.confirm({title:'按原请求查询与恢复',content:'保留原渠道单号，先核对原结果；不会新建退款来规避未知结果。',onOk:()=>this.perform('/tasks/'+this.task.id+'/recover',{expectedVersion:this.task.version,reason:this.reason.trim(),retry:this.retry})})},late(){if(this.reason.trim().length<2){this.error='请填写处理原因。';return}this.$Modal.confirm({title:'建立迟到付款原路退回义务',content:'仅适用于原付款保护状态，不复活订单、不恢复履约；实际退款需取得渠道成功证据。',onOk:()=>this.perform('/orders/'+this.data.orderId+'/late-refund',{reason:this.reason.trim()})})},async perform(path,body){this.busy=true;this.error='';try{await s45Commands.run(this.operationName,path,body);this.$Message.success('原操作已记录，请核对后续状态');this.load()}catch(e){this.error=e.message}finally{this.revision++;this.busy=false}},recovered(){this.revision++;this.load()}}};
</script>
